def normalize_ws(s):
    return ' '.join(s.split())

def strip_punct(s):
    return s.replace('.', '')

files.stats.py:
def median(xs):
    xs = sorted(xs)
    return xs[len(xs)//2]

files.export.py:
def to_csv(rows):
    sep = chr(10)
    return sep.join(','.join(str(c) for c in r) for r in rows)

